(7,'diet','Balanced Korean Diet Plan (19-29, Male)','{"avoid": ["excessive alcohol", "sugary beverages", "late-night eating", "excessive sodium (>2000mg/day)"], "macros": {"fat_g": 72, "fat_pct": 25, "protein_g": 130, "protein_pct": 20, "carbohydrate_g": 358, "carbohydrate_pct": 55}, "guidelines": ["Half the plate should be vegetables (banchan)", "Include fermented foods daily (kimchi, doenjang)", "Limit processed foods and instant noodles", "Reduce sodium: use low-sodium soy sauce and gochujang", "Eat whole grains (brown rice, barley) instead of white rice", "Fish 2-3 times per week for omega-3"], "meal_pattern": {"lunch_pct": 35, "snack_pct": 10, "dinner_pct": 30, "breakfast_pct": 25, "meals_per_day": 3, "snacks_per_day": 1}, "micronutrients": {"iron_mg": 10, "calcium_mg": 800, "fiber_g_min": 25, "sodium_mg_max": 2000, "vitamin_d_mcg": 10}, "daily_calories_kcal": 2600}'::jsonb,'A','Korean Nutrition Society DRIs 2020'),
